package com.bloodmoonrises;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class BloodMoonRisesPluginTest
{
    public static void main(String[] args) throws Exception
    {
        ExternalPluginManager.loadBuiltin(BloodMoonRisesPlugin.class);
        RuneLite.main(args);
    }
}

package com.bloodmoonrises;

import org.junit.Test;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class QuestDataTest
{
    @Test
    public void stepsAreNonEmptyAndWellFormed()
    {
        assertFalse(QuestData.STEPS.isEmpty());
        for (QuestStep step : QuestData.STEPS)
        {
            assertFalse(step.getPhase().trim().isEmpty());
            assertFalse(step.getText().trim().isEmpty());
        }
    }

    @Test
    public void coversAllTwelvePhasesAndCompletion()
    {
        for (int phase = 1; phase <= 12; phase++)
        {
            final String prefix = phase + ".";
            assertTrue("Missing phase " + phase,
                QuestData.STEPS.stream().anyMatch(s -> s.getPhase().startsWith(prefix)));
        }
        assertTrue(QuestData.STEPS.get(QuestData.STEPS.size() - 1).getPhase().startsWith("Complete"));
    }

    @Test
    public void trackingMetadataIsWellFormed()
    {
        boolean anyTracked = false;
        for (QuestStep step : QuestData.STEPS)
        {
            for (String item : step.getTrackedItems())
            {
                assertFalse("blank tracked item", item.trim().isEmpty());
            }
            anyTracked |= step.hasTrackedItems();
        }
        assertTrue(anyTracked);
    }

    @Test
    public void chatMatchingIsCaseInsensitive()
    {
        QuestStep mineStep = QuestData.STEPS.stream()
            .filter(s -> !s.getChatTriggers().isEmpty())
            .findFirst()
            .orElseThrow(IllegalStateException::new);
        String trigger = mineStep.getChatTriggers().get(0);
        assertTrue(mineStep.matchesChat("Prefix " + trigger.toUpperCase() + " suffix"));
        assertFalse(mineStep.matchesChat("Unrelated message"));
    }
}

package com.bloodmoonrises;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup(BloodMoonRisesConfig.GROUP)
public interface BloodMoonRisesConfig extends Config
{
    String GROUP = "bloodmoonrises";
    String CURRENT_STEP_KEY = "currentStep";

    @ConfigItem(
        keyName = "showOverlay",
        name = "Show step overlay",
        description = "Show the current quest step as an on-screen overlay",
        position = 1
    )
    default boolean showOverlay()
    {
        return true;
    }

    @ConfigItem(
        keyName = "showDetails",
        name = "Show puzzle/boss details",
        description = "Include puzzle solutions and boss mechanics in the overlay",
        position = 2
    )
    default boolean showDetails()
    {
        return true;
    }

    @ConfigItem(
        keyName = "highlightTargets",
        name = "Highlight NPCs/objects & path",
        description = "Highlight the current step's NPCs and objects in the scene, mark the travel target tile, "
            + "and draw a minimap/world map guide toward it",
        position = 3
    )
    default boolean highlightTargets()
    {
        return true;
    }

    @ConfigItem(
        keyName = "trackItems",
        name = "Track step items",
        description = "Color each step's tracked items in the panel: green = carried/equipped, "
            + "white = in your bank, red = not seen. Open your bank once to sync bank contents.",
        position = 4
    )
    default boolean trackItems()
    {
        return true;
    }

    @ConfigItem(
        keyName = "autoAdvance",
        name = "Auto-advance on chat messages",
        description = "Advance the current step when a matching game message appears, "
            + "and jump to the final step when the quest complete screen shows",
        position = 5
    )
    default boolean autoAdvance()
    {
        return true;
    }

    @ConfigItem(
        keyName = "progressVarbit",
        name = "Progress varbit ID",
        description = "Varbit tracking quest progress, for auto-advancing steps. "
            + "Leave at 0 (manual mode) until the community documents the varbit for The Blood Moon Rises.",
        position = 7
    )
    default int progressVarbit()
    {
        return 0;
    }

    @ConfigItem(
        keyName = CURRENT_STEP_KEY,
        name = "",
        description = "",
        hidden = true
    )
    default int currentStep()
    {
        return 0;
    }
}

package com.bloodmoonrises;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import lombok.Getter;
import net.runelite.api.coords.WorldPoint;

@Getter
public class QuestStep
{
    private final String phase;
    private final String text;
    // Extra detail: puzzle solutions, boss mechanics, warnings.
    private String detail;
    // Items needed for this step (shown in the panel dropdown and overlay).
    private String items;
    // Concrete item names to live-track against inventory/equipment/bank.
    // Matched case-insensitively as a substring of the item name, so "Pickaxe"
    // matches "Rune pickaxe" and "Super restore" matches "Super restore(4)".
    private final List<String> trackedItems = new ArrayList<>();
    // Chat-message phrases that mark this step complete (advance to the next step).
    private final List<String> chatTriggers = new ArrayList<>();
    // NPC/GameObject names to highlight in the scene while this step is active.
    private final List<String> highlights = new ArrayList<>();
    // Where to go for this step; drives the tile highlight, minimap guide and world map marker.
    private WorldPoint target;

    private QuestStep(String phase, String text)
    {
        this.phase = phase;
        this.text = text;
    }

    static QuestStep step(String phase, String text)
    {
        return new QuestStep(phase, text);
    }

    QuestStep detail(String detail)
    {
        this.detail = detail;
        return this;
    }

    QuestStep items(String items)
    {
        this.items = items;
        return this;
    }

    QuestStep tracked(String... names)
    {
        trackedItems.addAll(Arrays.asList(names));
        return this;
    }

    QuestStep onChat(String... phrases)
    {
        chatTriggers.addAll(Arrays.asList(phrases));
        return this;
    }

    QuestStep highlight(String... names)
    {
        highlights.addAll(Arrays.asList(names));
        return this;
    }

    QuestStep target(int x, int y, int plane)
    {
        this.target = new WorldPoint(x, y, plane);
        return this;
    }

    public boolean hasDetail()
    {
        return detail != null && !detail.isEmpty();
    }

    public boolean hasItems()
    {
        return items != null && !items.isEmpty();
    }

    public boolean hasTrackedItems()
    {
        return !trackedItems.isEmpty();
    }

    // Message with chat tags already stripped.
    public boolean matchesChat(String message)
    {
        if (message == null)
        {
            return false;
        }
        String lower = message.toLowerCase();
        for (String trigger : chatTriggers)
        {
            if (lower.contains(trigger.toLowerCase()))
            {
                return true;
            }
        }
        return false;
    }

    public boolean matchesHighlight(String name)
    {
        if (name == null)
        {
            return false;
        }
        for (String h : highlights)
        {
            if (name.equalsIgnoreCase(h))
            {
                return true;
            }
        }
        return false;
    }
}

package com.bloodmoonrises;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.Polygon;
import java.awt.Shape;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.NPC;
import net.runelite.api.Player;
import net.runelite.api.TileObject;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.Perspective;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayUtil;

/**
 * Highlights the current step's NPCs/objects and marks the travel target tile
 * plus a minimap guide line toward it.
 */
public class SceneHighlightOverlay extends Overlay
{
    private static final Color NPC_COLOR = new Color(0, 220, 255);
    private static final Color OBJECT_COLOR = new Color(80, 255, 100);
    private static final Color TARGET_COLOR = new Color(255, 140, 0);

    private final BloodMoonRisesPlugin plugin;
    private final BloodMoonRisesConfig config;

    @Inject
    public SceneHighlightOverlay(BloodMoonRisesPlugin plugin, BloodMoonRisesConfig config)
    {
        this.plugin = plugin;
        this.config = config;
        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_SCENE);
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        if (!config.highlightTargets())
        {
            return null;
        }

        Client client = plugin.getClient();

        for (NPC npc : plugin.getHighlightedNpcs())
        {
            Shape hull = npc.getConvexHull();
            if (hull != null)
            {
                OverlayUtil.renderPolygon(graphics, toPolygon(hull), NPC_COLOR);
            }
        }

        for (TileObject obj : plugin.getHighlightedObjects())
        {
            Shape clickbox = obj.getClickbox();
            if (clickbox != null)
            {
                graphics.setColor(OBJECT_COLOR);
                graphics.setStroke(new BasicStroke(2));
                graphics.draw(clickbox);
                graphics.setColor(new Color(OBJECT_COLOR.getRed(), OBJECT_COLOR.getGreen(), OBJECT_COLOR.getBlue(), 40));
                graphics.fill(clickbox);
            }
        }

        WorldPoint target = plugin.getStep().getTarget();
        if (target != null)
        {
            renderTargetGuide(graphics, client, target);
        }

        return null;
    }

    private void renderTargetGuide(Graphics2D graphics, Client client, WorldPoint target)
    {
        Player player = client.getLocalPlayer();
        if (player == null)
        {
            return;
        }

        // Target tile in the loaded scene: draw a tile marker.
        if (target.getPlane() == client.getPlane())
        {
            LocalPoint lp = LocalPoint.fromWorld(client, target);
            if (lp != null)
            {
                Polygon tile = Perspective.getCanvasTilePoly(client, lp);
                if (tile != null)
                {
                    OverlayUtil.renderPolygon(graphics, tile, TARGET_COLOR);
                    net.runelite.api.Point text = Perspective.getCanvasTextLocation(client, graphics, lp, "Go here", 40);
                    if (text != null)
                    {
                        OverlayUtil.renderTextLocation(graphics, text, "Go here", TARGET_COLOR);
                    }
                }

                // Minimap guide toward the target while it's loaded.
                net.runelite.api.Point mini = Perspective.localToMinimap(client, lp, 2500);
                net.runelite.api.Point playerMini = Perspective.localToMinimap(client, player.getLocalLocation());
                if (mini != null && playerMini != null)
                {
                    graphics.setColor(TARGET_COLOR);
                    graphics.setStroke(new BasicStroke(2));
                    graphics.drawLine(playerMini.getX(), playerMini.getY(), mini.getX(), mini.getY());
                    graphics.fillOval(mini.getX() - 3, mini.getY() - 3, 6, 6);
                }
            }
        }
    }

    private static Polygon toPolygon(Shape shape)
    {
        if (shape instanceof Polygon)
        {
            return (Polygon) shape;
        }
        Polygon poly = new Polygon();
        java.awt.geom.PathIterator it = shape.getPathIterator(null, 1.0);
        double[] coords = new double[6];
        while (!it.isDone())
        {
            int type = it.currentSegment(coords);
            if (type != java.awt.geom.PathIterator.SEG_CLOSE)
            {
                poly.addPoint((int) coords[0], (int) coords[1]);
            }
            it.next();
        }
        return poly;
    }
}

package com.bloodmoonrises;

import com.google.inject.Provides;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.CopyOnWriteArrayList;
import javax.inject.Inject;
import lombok.Getter;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.InventoryID;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.NPC;
import net.runelite.api.ObjectComposition;
import net.runelite.api.TileObject;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.DecorativeObjectDespawned;
import net.runelite.api.events.DecorativeObjectSpawned;
import net.runelite.api.events.GameObjectDespawned;
import net.runelite.api.events.GameObjectSpawned;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GroundObjectDespawned;
import net.runelite.api.events.GroundObjectSpawned;
import net.runelite.api.events.NpcDespawned;
import net.runelite.api.events.NpcSpawned;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.events.VarbitChanged;
import net.runelite.api.events.WallObjectDespawned;
import net.runelite.api.events.WallObjectSpawned;
import net.runelite.api.events.WidgetLoaded;
import net.runelite.api.widgets.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.game.ItemManager;
import net.runelite.client.util.Text;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.ui.overlay.worldmap.WorldMapPoint;
import net.runelite.client.ui.overlay.worldmap.WorldMapPointManager;
import net.runelite.client.util.ImageUtil;

@PluginDescriptor(
    name = "Blood Moon Rises Helper",
    description = "Quest helper for The Blood Moon Rises: step-by-step guidance, puzzle solutions and boss mechanics",
    tags = {"quest", "helper", "myreque", "vampyre", "drakan"}
)
public class BloodMoonRisesPlugin extends Plugin
{
    @Inject
    private Client client;

    @Inject
    private ClientToolbar clientToolbar;

    @Inject
    private OverlayManager overlayManager;

    @Inject
    private BloodMoonRisesOverlay overlay;

    @Inject
    private SceneHighlightOverlay sceneOverlay;

    @Inject
    private BloodMoonRisesConfig config;

    @Inject
    private ConfigManager configManager;

    @Inject
    private WorldMapPointManager worldMapPointManager;

    @Inject
    private ItemManager itemManager;

    @Inject
    private ClientThread clientThread;

    private BloodMoonRisesPanel panel;
    private NavigationButton navButton;
    private WorldMapPoint mapPoint;
    private BufferedImage icon;

    @Getter
    private int currentStep;

    @Getter
    private final List<NPC> npcs = new CopyOnWriteArrayList<>();

    @Getter
    private final List<TileObject> objects = new CopyOnWriteArrayList<>();

    private final Map<Integer, String> objectNameCache = new HashMap<>();

    // Lowercased item names currently in each container. Bank contents are only
    // known once the player has opened their bank this session.
    private final Set<String> inventoryItems = ConcurrentHashMap.newKeySet();
    private final Set<String> equipmentItems = ConcurrentHashMap.newKeySet();
    private final Set<String> bankItems = ConcurrentHashMap.newKeySet();

    @Getter
    private boolean bankSeen;

    public enum ItemState
    {
        CARRIED,   // in inventory or equipped
        BANKED,    // seen in the bank
        MISSING    // not seen anywhere (yet)
    }

    @Provides
    BloodMoonRisesConfig provideConfig(ConfigManager configManager)
    {
        return configManager.getConfig(BloodMoonRisesConfig.class);
    }

    @Override
    protected void startUp()
    {
        currentStep = Math.max(0, Math.min(config.currentStep(), QuestData.STEPS.size() - 1));

        panel = new BloodMoonRisesPanel(this);
        icon = ImageUtil.loadImageResource(getClass(), "/icon.png");
        navButton = NavigationButton.builder()
            .tooltip("Blood Moon Rises Helper")
            .icon(icon)
            .priority(7)
            .panel(panel)
            .build();
        clientToolbar.addNavigation(navButton);

        overlayManager.add(overlay);
        overlayManager.add(sceneOverlay);
        updateMapPoint();
    }

    @Override
    protected void shutDown()
    {
        overlayManager.remove(overlay);
        overlayManager.remove(sceneOverlay);
        clientToolbar.removeNavigation(navButton);
        removeMapPoint();
        npcs.clear();
        objects.clear();
        objectNameCache.clear();
    }

    @Subscribe
    public void onGameStateChanged(GameStateChanged event)
    {
        if (event.getGameState() == GameState.LOADING)
        {
            objects.clear();
        }
        else if (event.getGameState() == GameState.LOGIN_SCREEN || event.getGameState() == GameState.HOPPING)
        {
            npcs.clear();
            objects.clear();
            if (event.getGameState() == GameState.LOGIN_SCREEN)
            {
                // A different character may log in next; forget what we saw.
                inventoryItems.clear();
                equipmentItems.clear();
                bankItems.clear();
                bankSeen = false;
            }
        }
    }

    @Subscribe
    public void onNpcSpawned(NpcSpawned event)
    {
        npcs.add(event.getNpc());
    }

    @Subscribe
    public void onNpcDespawned(NpcDespawned event)
    {
        npcs.remove(event.getNpc());
    }

    @Subscribe
    public void onGameObjectSpawned(GameObjectSpawned event)
    {
        objects.add(event.getGameObject());
    }

    @Subscribe
    public void onGameObjectDespawned(GameObjectDespawned event)
    {
        objects.remove(event.getGameObject());
    }

    @Subscribe
    public void onWallObjectSpawned(WallObjectSpawned event)
    {
        objects.add(event.getWallObject());
    }

    @Subscribe
    public void onWallObjectDespawned(WallObjectDespawned event)
    {
        objects.remove(event.getWallObject());
    }

    @Subscribe
    public void onGroundObjectSpawned(GroundObjectSpawned event)
    {
        objects.add(event.getGroundObject());
    }

    @Subscribe
    public void onGroundObjectDespawned(GroundObjectDespawned event)
    {
        objects.remove(event.getGroundObject());
    }

    @Subscribe
    public void onDecorativeObjectSpawned(DecorativeObjectSpawned event)
    {
        objects.add(event.getDecorativeObject());
    }

    @Subscribe
    public void onDecorativeObjectDespawned(DecorativeObjectDespawned event)
    {
        objects.remove(event.getDecorativeObject());
    }

    @Subscribe
    public void onItemContainerChanged(ItemContainerChanged event)
    {
        int id = event.getContainerId();
        if (id == InventoryID.INVENTORY.getId())
        {
            refill(inventoryItems, event.getItemContainer());
        }
        else if (id == InventoryID.EQUIPMENT.getId())
        {
            refill(equipmentItems, event.getItemContainer());
        }
        else if (id == InventoryID.BANK.getId())
        {
            bankSeen = true;
            refill(bankItems, event.getItemContainer());
        }
        else
        {
            return;
        }
        if (panel != null)
        {
            panel.refresh();
        }
    }

    // Runs on the client thread (event handler), so item lookups are safe.
    private void refill(Set<String> set, ItemContainer container)
    {
        Set<String> names = new HashSet<>();
        if (container != null)
        {
            for (Item item : container.getItems())
            {
                if (item.getId() > 0)
                {
                    names.add(itemManager.getItemComposition(item.getId()).getName().toLowerCase());
                }
            }
        }
        set.retainAll(names);
        set.addAll(names);
    }

    public ItemState getItemState(String trackedName)
    {
        String needle = trackedName.toLowerCase();
        if (containsMatch(inventoryItems, needle) || containsMatch(equipmentItems, needle))
        {
            return ItemState.CARRIED;
        }
        if (containsMatch(bankItems, needle))
        {
            return ItemState.BANKED;
        }
        return ItemState.MISSING;
    }

    private static boolean containsMatch(Set<String> itemNames, String needle)
    {
        for (String name : itemNames)
        {
            if (name.contains(needle))
            {
                return true;
            }
        }
        return false;
    }

    @Subscribe
    public void onChatMessage(ChatMessage event)
    {
        if (!config.autoAdvance())
        {
            return;
        }
        ChatMessageType type = event.getType();
        if (type != ChatMessageType.GAMEMESSAGE && type != ChatMessageType.SPAM
            && type != ChatMessageType.MESBOX)
        {
            return;
        }
        String message = Text.removeTags(event.getMessage());
        // Only look a few steps ahead so a generic phrase can't jump the guide
        // across the whole quest.
        int limit = Math.min(currentStep + 3, QuestData.STEPS.size() - 1);
        for (int i = currentStep; i < limit; i++)
        {
            if (QuestData.STEPS.get(i).matchesChat(message))
            {
                setStep(i + 1);
                return;
            }
        }
    }

    @Subscribe
    public void onWidgetLoaded(WidgetLoaded event)
    {
        if (event.getGroupId() == InterfaceID.QUEST_COMPLETED && config.autoAdvance())
        {
            // Widget children aren't populated until after the load event.
            clientThread.invokeLater(this::checkQuestComplete);
        }
    }

    private void checkQuestComplete()
    {
        for (int child = 0; child <= 15; child++)
        {
            Widget w = client.getWidget(InterfaceID.QUEST_COMPLETED, child);
            if (w != null && w.getText() != null && w.getText().contains("Blood Moon Rises"))
            {
                setStep(QuestData.STEPS.size() - 1);
                return;
            }
        }
    }

    @Subscribe
    public void onVarbitChanged(VarbitChanged event)
    {
        int varbitId = config.progressVarbit();
        if (varbitId > 0 && event.getVarbitId() == varbitId)
        {
            panel.refresh();
        }
    }

    public QuestStep getStep()
    {
        return QuestData.STEPS.get(currentStep);
    }

    public void setStep(int index)
    {
        currentStep = Math.max(0, Math.min(index, QuestData.STEPS.size() - 1));
        configManager.setConfiguration(BloodMoonRisesConfig.GROUP, BloodMoonRisesConfig.CURRENT_STEP_KEY, currentStep);
        updateMapPoint();
        if (panel != null)
        {
            panel.refresh();
        }
    }

    public void nextStep()
    {
        setStep(currentStep + 1);
    }

    public void previousStep()
    {
        setStep(currentStep - 1);
    }

    // Must be called on the client thread (render/event handlers are fine).
    public String getObjectName(TileObject object)
    {
        return objectNameCache.computeIfAbsent(object.getId(), id ->
        {
            ObjectComposition def = client.getObjectDefinition(id);
            if (def == null)
            {
                return "";
            }
            if (def.getImpostorIds() != null)
            {
                def = def.getImpostor();
            }
            return def == null ? "" : def.getName();
        });
    }

    public List<NPC> getHighlightedNpcs()
    {
        QuestStep step = getStep();
        List<NPC> out = new ArrayList<>();
        for (NPC npc : npcs)
        {
            if (step.matchesHighlight(npc.getName()))
            {
                out.add(npc);
            }
        }
        return out;
    }

    public List<TileObject> getHighlightedObjects()
    {
        QuestStep step = getStep();
        List<TileObject> out = new ArrayList<>();
        for (TileObject obj : objects)
        {
            if (step.matchesHighlight(getObjectName(obj)))
            {
                out.add(obj);
            }
        }
        return out;
    }

    private void updateMapPoint()
    {
        removeMapPoint();
        QuestStep step = getStep();
        if (step.getTarget() != null && icon != null)
        {
            mapPoint = new WorldMapPoint(step.getTarget(), icon);
            mapPoint.setTooltip("Blood Moon Rises: " + step.getPhase());
            mapPoint.setJumpOnClick(true);
            worldMapPointManager.add(mapPoint);
        }
    }

    private void removeMapPoint()
    {
        if (mapPoint != null)
        {
            worldMapPointManager.remove(mapPoint);
            mapPoint = null;
        }
    }

    public Client getClient()
    {
        return client;
    }

    public BloodMoonRisesConfig getConfig()
    {
        return config;
    }
}

package com.bloodmoonrises;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.Cursor;
import java.awt.GridLayout;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.SwingUtilities;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.PluginPanel;

public class BloodMoonRisesPanel extends PluginPanel
{
    private static final Color CURRENT_BG = new Color(90, 30, 30);
    private static final Color DONE_FG = new Color(110, 110, 110);

    private final BloodMoonRisesPlugin plugin;
    private final JLabel progressLabel = new JLabel();
    private final List<PhaseSection> sections = new ArrayList<>();

    public BloodMoonRisesPanel(BloodMoonRisesPlugin plugin)
    {
        this.plugin = plugin;

        setLayout(new BorderLayout(0, 8));
        setBorder(BorderFactory.createEmptyBorder(10, 10, 10, 10));
        setBackground(ColorScheme.DARK_GRAY_COLOR);

        JLabel title = new JLabel("The Blood Moon Rises");
        title.setForeground(new Color(200, 40, 40));
        title.setFont(title.getFont().deriveFont(16f));
        progressLabel.setForeground(Color.LIGHT_GRAY);

        // Step cycling controls.
        JButton prev = new JButton("< Back");
        JButton next = new JButton("Done, next >");
        prev.setToolTipText("Cycle back a step");
        next.setToolTipText("Mark this step done and advance");
        prev.addActionListener(e -> plugin.previousStep());
        next.addActionListener(e -> plugin.nextStep());
        JPanel buttons = new JPanel(new GridLayout(1, 2, 6, 0));
        buttons.setBackground(ColorScheme.DARK_GRAY_COLOR);
        buttons.add(prev);
        buttons.add(next);

        JPanel header = new JPanel();
        header.setLayout(new BoxLayout(header, BoxLayout.Y_AXIS));
        header.setBackground(ColorScheme.DARK_GRAY_COLOR);
        header.add(title);
        header.add(progressLabel);
        header.add(Box.createVerticalStrut(6));
        header.add(buttons);

        // Collapsible phase sections; steps are clickable to jump anywhere.
        JPanel sectionsPanel = new JPanel();
        sectionsPanel.setLayout(new BoxLayout(sectionsPanel, BoxLayout.Y_AXIS));
        sectionsPanel.setBackground(ColorScheme.DARK_GRAY_COLOR);

        sectionsPanel.add(buildOverviewSection());
        sectionsPanel.add(Box.createVerticalStrut(4));

        Map<String, List<Integer>> phases = new LinkedHashMap<>();
        for (int i = 0; i < QuestData.STEPS.size(); i++)
        {
            phases.computeIfAbsent(QuestData.STEPS.get(i).getPhase(), k -> new ArrayList<>()).add(i);
        }
        for (Map.Entry<String, List<Integer>> entry : phases.entrySet())
        {
            PhaseSection section = new PhaseSection(entry.getKey(), entry.getValue());
            sections.add(section);
            sectionsPanel.add(section);
            sectionsPanel.add(Box.createVerticalStrut(4));
        }

        add(header, BorderLayout.NORTH);
        add(sectionsPanel, BorderLayout.CENTER);

        refresh();
    }

    public void refresh()
    {
        SwingUtilities.invokeLater(() ->
        {
            int current = plugin.getCurrentStep();
            progressLabel.setText("Step " + (current + 1) + " of " + QuestData.STEPS.size()
                + "  -  " + QuestData.STEPS.get(current).getPhase());
            for (PhaseSection section : sections)
            {
                section.refresh(current);
            }
            revalidate();
            repaint();
        });
    }

    // Collapsible quest overview shown above phase 1: requirements, items,
    // item-color legend, rewards and quest enemies.
    private JPanel buildOverviewSection()
    {
        JPanel section = new JPanel(new BorderLayout());
        section.setBackground(ColorScheme.DARK_GRAY_COLOR);
        section.setAlignmentX(Component.LEFT_ALIGNMENT);

        JLabel content = new JLabel("<html><body style='width:150px'>"
            + "<b>Requirements</b><br>" + QuestData.REQUIREMENTS
            + "<br><br><b>Items overview</b><br>" + QuestData.ITEMS
            + "<br><br><b>Item colors</b><br>"
            + "<font color='#59d97c'>green = carried/equipped</font><br>"
            + "<font color='#ffffff'>white = in your bank</font><br>"
            + "<font color='#e57373'>red = not found</font><br>"
            + "<i>Open your bank once to sync its contents.</i>"
            + "<br><br><b>Rewards</b><br>" + QuestData.REWARDS
            + "<br><br><b>Enemies</b><br>" + QuestData.ENEMIES
            + "</body></html>");
        content.setForeground(Color.LIGHT_GRAY);
        content.setFont(net.runelite.client.ui.FontManager.getRunescapeSmallFont());

        JPanel contentWrap = new JPanel(new BorderLayout());
        contentWrap.setBackground(ColorScheme.DARK_GRAY_COLOR);
        contentWrap.setBorder(BorderFactory.createEmptyBorder(4, 8, 4, 0));
        contentWrap.add(content, BorderLayout.CENTER);
        contentWrap.setVisible(false);

        JButton headerButton = new JButton("▶ Overview");
        headerButton.setHorizontalAlignment(JButton.LEFT);
        headerButton.setFocusPainted(false);
        headerButton.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        headerButton.setForeground(Color.ORANGE);
        headerButton.setFont(net.runelite.client.ui.FontManager.getRunescapeSmallFont());
        headerButton.setMargin(new java.awt.Insets(4, 4, 4, 4));
        headerButton.addActionListener(e ->
        {
            boolean show = !contentWrap.isVisible();
            contentWrap.setVisible(show);
            headerButton.setText((show ? "▼ " : "▶ ") + "Overview");
            revalidate();
        });

        section.add(headerButton, BorderLayout.NORTH);
        section.add(contentWrap, BorderLayout.CENTER);
        return section;
    }

    private final class PhaseSection extends JPanel
    {
        private final List<Integer> stepIndices;
        private final JButton headerButton;
        private final JPanel content;
        private final List<StepRow> rows = new ArrayList<>();
        private boolean expanded;
        private boolean userToggled;

        PhaseSection(String phase, List<Integer> stepIndices)
        {
            this.stepIndices = stepIndices;

            setLayout(new BorderLayout());
            setBackground(ColorScheme.DARK_GRAY_COLOR);
            setAlignmentX(Component.LEFT_ALIGNMENT);

            content = new JPanel();

            headerButton = new JButton();
            headerButton.setHorizontalAlignment(JButton.LEFT);
            headerButton.setFocusPainted(false);
            headerButton.setBackground(ColorScheme.DARKER_GRAY_COLOR);
            headerButton.setForeground(Color.ORANGE);
            headerButton.setFont(net.runelite.client.ui.FontManager.getRunescapeSmallFont());
            headerButton.setMargin(new java.awt.Insets(4, 4, 4, 4));
            headerButton.addActionListener(e ->
            {
                expanded = !expanded;
                userToggled = true;
                content.setVisible(expanded);
                updateHeaderText(phase);
                revalidate();
            });

            content.setLayout(new BoxLayout(content, BoxLayout.Y_AXIS));
            content.setBackground(ColorScheme.DARK_GRAY_COLOR);
            content.setBorder(BorderFactory.createEmptyBorder(2, 8, 2, 0));
            for (int idx : stepIndices)
            {
                StepRow row = new StepRow(idx);
                rows.add(row);
                content.add(row);
                content.add(Box.createVerticalStrut(3));
            }
            content.setVisible(false);
            updateHeaderText(phase);

            add(headerButton, BorderLayout.NORTH);
            add(content, BorderLayout.CENTER);
        }

        private void updateHeaderText(String phase)
        {
            headerButton.setText((expanded ? "▼ " : "▶ ") + phase + " (" + stepIndices.size() + ")");
        }

        void refresh(int currentStep)
        {
            boolean containsCurrent = stepIndices.contains(currentStep);
            // Auto-expand the active phase (and collapse others) unless the user
            // has manually toggled this section.
            if (!userToggled)
            {
                expanded = containsCurrent;
                content.setVisible(expanded);
                updateHeaderText(QuestData.STEPS.get(stepIndices.get(0)).getPhase());
            }
            if (containsCurrent)
            {
                userToggled = false; // re-enable auto behavior once progress moves on
            }
            for (StepRow row : rows)
            {
                row.refresh(currentStep);
            }
        }
    }

    private final class StepRow extends JPanel
    {
        private final int index;
        private final JLabel label = new JLabel();

        StepRow(int index)
        {
            this.index = index;
            setLayout(new BorderLayout());
            setBackground(ColorScheme.DARKER_GRAY_COLOR);
            setBorder(BorderFactory.createEmptyBorder(4, 6, 4, 6));
            setAlignmentX(Component.LEFT_ALIGNMENT);
            setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
            setToolTipText("Click to jump to this step");

            label.setText(buildHtml());
            label.setFont(net.runelite.client.ui.FontManager.getRunescapeSmallFont());
            add(label, BorderLayout.CENTER);

            MouseAdapter click = new MouseAdapter()
            {
                @Override
                public void mousePressed(MouseEvent e)
                {
                    plugin.setStep(index);
                }
            };
            addMouseListener(click);
            label.addMouseListener(click);
        }

        private String buildHtml()
        {
            QuestStep step = QuestData.STEPS.get(index);
            StringBuilder html = new StringBuilder("<html><body style='width:150px'>").append(step.getText());
            if (step.hasItems())
            {
                html.append("<br><font color='#8cc8ff'><i>").append(step.getItems()).append("</i></font>");
            }
            if (step.hasTrackedItems() && plugin.getConfig().trackItems())
            {
                html.append("<br>");
                boolean first = true;
                for (String item : step.getTrackedItems())
                {
                    if (!first)
                    {
                        html.append("<font color='#888888'> · </font>");
                    }
                    first = false;
                    html.append("<font color='").append(itemColor(item)).append("'>")
                        .append(item).append("</font>");
                }
            }
            html.append("</body></html>");
            return html.toString();
        }

        private String itemColor(String item)
        {
            switch (plugin.getItemState(item))
            {
                case CARRIED:
                    return "#59d97c";
                case BANKED:
                    return "#ffffff";
                default:
                    return "#e57373";
            }
        }

        void refresh(int currentStep)
        {
            label.setText(buildHtml());
            if (index == currentStep)
            {
                setBackground(CURRENT_BG);
                label.setForeground(Color.WHITE);
            }
            else if (index < currentStep)
            {
                setBackground(ColorScheme.DARKER_GRAY_COLOR);
                label.setForeground(DONE_FG);
            }
            else
            {
                setBackground(ColorScheme.DARKER_GRAY_COLOR);
                label.setForeground(Color.LIGHT_GRAY);
            }
        }
    }
}

package com.bloodmoonrises;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

public class BloodMoonRisesOverlay extends OverlayPanel
{
    private static final Color BLOOD_RED = new Color(170, 20, 20);
    private static final Color ITEM_COLOR = new Color(140, 200, 255);
    private static final Color TARGET_COLOR = new Color(255, 140, 0);

    private final Client client;
    private final BloodMoonRisesPlugin plugin;
    private final BloodMoonRisesConfig config;

    @Inject
    public BloodMoonRisesOverlay(Client client, BloodMoonRisesPlugin plugin, BloodMoonRisesConfig config)
    {
        this.client = client;
        this.plugin = plugin;
        this.config = config;
        setPosition(OverlayPosition.TOP_LEFT);
        setPreferredSize(new Dimension(280, 0));
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        if (!config.showOverlay())
        {
            return null;
        }

        QuestStep step = plugin.getStep();

        panelComponent.getChildren().add(TitleComponent.builder()
            .text("The Blood Moon Rises")
            .color(BLOOD_RED)
            .build());

        panelComponent.getChildren().add(LineComponent.builder()
            .left(step.getPhase())
            .leftColor(Color.ORANGE)
            .right((plugin.getCurrentStep() + 1) + "/" + QuestData.STEPS.size())
            .build());

        panelComponent.getChildren().add(LineComponent.builder()
            .left(step.getText())
            .build());

        if (step.hasItems())
        {
            panelComponent.getChildren().add(LineComponent.builder()
                .left("Items: " + step.getItems())
                .leftColor(ITEM_COLOR)
                .build());
        }

        if (config.showDetails() && step.hasDetail())
        {
            panelComponent.getChildren().add(LineComponent.builder()
                .left(step.getDetail())
                .leftColor(new Color(200, 200, 160))
                .build());
        }

        // Direction/distance readout toward the step's travel target.
        WorldPoint target = step.getTarget();
        Player player = client.getLocalPlayer();
        if (config.highlightTargets() && target != null && player != null)
        {
            WorldPoint pos = player.getWorldLocation();
            int dx = target.getX() - pos.getX();
            int dy = target.getY() - pos.getY();
            int dist = Math.max(Math.abs(dx), Math.abs(dy));
            if (dist > 3)
            {
                panelComponent.getChildren().add(LineComponent.builder()
                    .left("Head " + direction(dx, dy) + " (" + dist + " tiles) - marked on world map")
                    .leftColor(TARGET_COLOR)
                    .build());
            }
        }

        return super.render(graphics);
    }

    private static String direction(int dx, int dy)
    {
        String ns = dy > 3 ? "north" : (dy < -3 ? "south" : "");
        String ew = dx > 3 ? "east" : (dx < -3 ? "west" : "");
        String dir = ns + (ns.isEmpty() || ew.isEmpty() ? "" : "-") + ew;
        return dir.isEmpty() ? "here" : dir;
    }
}
